def top_word_per_length(text):
    words = text.split()
    counts = {}
    for w in words:
        length = len(w)
        if length not in counts:
            counts[length] = {}
        counts[length][w] = counts[length].get(w, 0) + 1
    result = {}
    for length, freq in counts.items():
        best_word = None
        best_count = -1
        for w in sorted(freq):
            if freq[w] > best_count:
                best_count = freq[w]
                best_word = w
        result[length] = best_word
    return result

def interleave_rankings_weighted(list1, list2):
    seen = set()
    result = []
    i = j = 0
    while i < len(list1) or j < len(list2):
        chunk = list1[i:i + 2]
        i += len(chunk)
        for item in chunk:
            if item not in seen:
                seen.add(item)
                result.append(item)
        if j < len(list2):
            item = list2[j]
            j += 1
            if item not in seen:
                seen.add(item)
                result.append(item)
    return result

