from collections import deque

def rotate_dict_values(d, n):
    keys = sorted(d.keys())
    if not keys:
        return {}
    values = deque(d[k] for k in keys)
    values.rotate(n)
    return {k: v for k, v in zip(keys, values)}

def largest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    k, r = divmod(s, 9)
    if r == 0:
        digits_str = '9' * k + '0' * (d - k)
    else:
        digits_str = '9' * k + str(r) + '0' * (d - k - 1)
    return int(digits_str)

def running_distinct_count(lst):
